<?php
session_name('maison_session');
session_set_cookie_params(86400 * 30);
session_start();

// Verificar autenticação
if (empty($_SESSION['cliente_id'])) {
    header('Location: login.php');
    exit;
}

require_once 'config.php';

// Carregar produtos da cliente
$cliente_id = $_SESSION['cliente_id'];
$cliente_nome = $_SESSION['cliente_nome'] ?? '';
$primeiro_nome = explode(' ', $cliente_nome)[0] ?: 'Bem-vinda';

try {
    $pdo = new PDO(
        "mysql:host=" . DB_HOST . ";dbname=" . DB_NAME . ";charset=utf8mb4",
        DB_USER, DB_PASS,
        [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]
    );

    $stmt = $pdo->prepare("SELECT produto FROM acessos WHERE cliente_id = ?");
    $stmt->execute([$cliente_id]);
    $acessos = array_column($stmt->fetchAll(PDO::FETCH_ASSOC), 'produto');
} catch (PDOException $e) {
    $acessos = [];
}

function tem_acesso($acessos, $produto) {
    return in_array($produto, $acessos);
}

// Logout
if (isset($_GET['logout'])) {
    session_destroy();
    header('Location: login.php');
    exit;
}
?>
